-- Original geometric art. Standard keeps this project's original 14 by 16 pixel silhouette.
-- Smooth uses original antialiased sphere/iris/glint textures generated by tools/widgets/eyes/generate_assets.py.
local silhouette = {
    { 0, 7, 8, 2 }, { 0, 5, 12, 2 }, { 0, 0, 14, 8 },
    { 0, -5, 12, 2 }, { 0, -7, 8, 2 },
}
local white = {
    { 0, 6, 6, 2 }, { 0, 4, 10, 2 }, { 0, 0, 12, 6 },
    { 0, -4, 10, 2 }, { 0, -6, 6, 2 },
}
local palettes = {
    black = { 0.05, 0.05, 0.05 }, brown = { 0.40, 0.23, 0.10 },
    blue = { 0.16, 0.49, 0.94 }, hazel = { 0.56, 0.49, 0.20 },
    grey = { 0.53, 0.57, 0.61 }, red = { 0.88, 0.14, 0.12 },
    solidBlue = { 0.20, 0.65, 1.00, solid = true },
    solidOrange = { 1.00, 0.48, 0.12, solid = true },
    solidRed = { 1.00, 0.16, 0.12, solid = true },
    solidGreen = { 0.24, 1.00, 0.43, solid = true },
}
local assetRoot = "Interface\\AddOns\\Menubar_Eyes\\Assets\\"
local trailCount, trailInterval, trailLifetime = 6, 0.05, 0.28
local trailOpacity = 0.45

local function public(value)
    return type(issecretvalue) ~= "function" or not issecretvalue(value)
end

local function finite(value)
    return public(value) and type(value) == "number" and value == value
        and value > -math.huge and value < math.huge
end

local function ensureTexture(frame, regions, key, level)
    local texture = regions[key]
    if not texture then
        texture = frame:CreateTexture(nil, "ARTWORK", nil, level)
        -- Own the region before configuration so a failed setup can be cleaned up and retried.
        regions[key] = texture
        texture:Hide()
    end
    return texture
end

local function style(widget)
    return widget.settings.appearance == "smooth" and "smooth" or "standard"
end

local function ensureArt(widget, appearance)
    widget.eyes = widget.eyes or {}
    for index = 1, 2 do
        local eye = widget.eyes[index] or { border = {}, white = {} }
        widget.eyes[index] = eye
        if appearance == "smooth" then
            eye.smooth = eye.smooth or {}
            ensureTexture(widget.frame, eye.smooth, "orb", 0)
            ensureTexture(widget.frame, eye.smooth, "iris", 3)
            ensureTexture(widget.frame, eye.smooth, "glint", 4)
        else
            for row = 1, #silhouette do
                ensureTexture(widget.frame, eye.border, row, 0)
            end
            for row = 1, #white do ensureTexture(widget.frame, eye.white, row, 1) end
            ensureTexture(widget.frame, eye, "pupil", 3)
            ensureTexture(widget.frame, eye, "spark", 4)
        end
    end
end

local function clearTrail(eye)
    if eye.trails then
        for _, sample in ipairs(eye.trails) do
            if sample.texture then sample.texture:Hide() end
            sample.age = nil
        end
    end
    eye.trailX, eye.trailY = nil, nil
    eye.trailNext, eye.trailSampleAge = 1, trailInterval
end

local function clearTrails(widget)
    if widget.eyes then
        for _, eye in ipairs(widget.eyes) do clearTrail(eye) end
    end
end

local function create(widget)
    if widget.eyesReady then return end
    ensureArt(widget, style(widget))
    if not widget.eyesTrailHook then
        -- The host pauses updates while hidden; do not retain a frozen afterimage.
        widget.frame:HookScript("OnHide", function() clearTrails(widget) end)
        widget.eyesTrailHook = true
    end
    widget.eyesReady = true
    widget:SetText("")
end

local function position(texture, frame, x, y, width, height)
    texture:ClearAllPoints()
    texture:SetPoint("CENTER", frame, "CENTER", x, y)
    texture:SetSize(width, height)
    texture:Show()
end

local function updateTrail(widget, eye, eyeX, x, y, width, height, color, elapsed, active)
    if not active or not elapsed then
        clearTrail(eye)
        if active then eye.trailX, eye.trailY = x, y end
        return
    end
    if eye.trails then
        for _, sample in ipairs(eye.trails) do
            if sample.age then
                sample.age = sample.age + elapsed
                if sample.age >= trailLifetime then
                    sample.texture:Hide()
                    sample.age = nil
                else
                    sample.texture:SetAlpha(trailOpacity * (1 - sample.age / trailLifetime) ^ 2)
                end
            end
        end
    end
    local previousX, previousY = eye.trailX, eye.trailY
    eye.trailX, eye.trailY = x, y
    if previousX == nil then return end
    eye.trailSampleAge = math.min(trailInterval, eye.trailSampleAge or trailInterval) + elapsed
    local dx, dy = x - previousX, y - previousY
    if dx * dx + dy * dy < (0.02 * eye.factor) ^ 2 or eye.trailSampleAge < trailInterval then return end
    if not eye.trailsReady then
        eye.trails = eye.trails or {}
        for index = 1, trailCount do
            local sample = eye.trails[index] or {}
            eye.trails[index] = sample
            if not sample.ready then
                local texture = ensureTexture(widget.frame, sample, "texture", 2)
                texture:SetTexture(assetRoot .. "Glint.tga")
                -- A soft alpha trace remains visible on the white sclera; ADD would saturate it.
                texture:SetBlendMode("BLEND")
                texture:Hide()
                sample.ready = true
            end
        end
        eye.trailsReady = true
    end
    local index = eye.trailNext or 1
    local sample = eye.trails[index]
    sample.age = 0
    sample.texture:SetVertexColor(color[1], color[2], color[3], 1)
    sample.texture:SetAlpha(trailOpacity)
    position(sample.texture, (widget.content or widget.frame), eyeX + previousX, previousY, width, height)
    eye.trailNext = index % trailCount + 1
    eye.trailSampleAge = eye.trailSampleAge % trailInterval
end

local function hideStandard(eye)
    for _, texture in ipairs(eye.border) do texture:Hide() end
    for _, texture in ipairs(eye.white) do texture:Hide() end
    if eye.pupil then eye.pupil:Hide() end
    if eye.spark then eye.spark:Hide() end
end

local function hideSmooth(eye)
    if eye.smooth then
        for _, texture in pairs(eye.smooth) do texture:Hide() end
    end
end

local function size(widget)
    local requested = public(widget.settings.size) and tonumber(widget.settings.size) or nil
    if not finite(requested) or requested < 8 or requested > 32 then requested = 16 end
    local available = (widget.content or widget.frame):GetHeight()
    if not finite(available) or available < 0 then available = 24 end
    -- The content frame already excludes the bar's framing. Keep the chosen
    -- height when it fits; older hosts still need their original edge allowance.
    if not widget.content then available = available - 4 end
    return math.min(requested, math.max(4, available)) / 16
end

local function cursor(widget)
    if type(GetCursorPosition) ~= "function" then return nil end
    if type(IsMouselooking) == "function" then
        local ok, looking = pcall(IsMouselooking)
        if not ok or not public(looking) or type(looking) ~= "boolean" or looking then return nil end
    end
    if type(IsCursorVisible) == "function" then
        local ok, visible = pcall(IsCursorVisible)
        if not ok or not public(visible) or type(visible) ~= "boolean" or not visible then return nil end
    end
    local ok, x, y = pcall(GetCursorPosition)
    if not ok or not finite(x) or not finite(y) then return nil end
    local scale = widget.frame:GetEffectiveScale()
    if not finite(scale) or scale <= 0 then return nil end
    x, y = x / scale, y / scale
    if not finite(x) or not finite(y) then return nil end
    return x, y, scale
end

local function update(widget, elapsed)
    if not widget.eyesReady then create(widget) end
    if widget.text ~= "" then widget:SetText("") end
    local appearance = style(widget)
    local color = palettes[widget.settings.iris] or palettes.black
    ensureArt(widget, appearance)
    local factor = size(widget)
    local width = 32 * factor + 8
    if widget.eyesWidth ~= width or widget.customWidth ~= width then
        widget:SetWidth(width)
        widget.eyesWidth = width
    end
    local centerX, centerY = (widget.content or widget.frame):GetCenter()
    if not finite(centerX) or not finite(centerY) then centerX, centerY = nil, nil end
    local cursorX, cursorY, cursorScale
    if widget.settings.followCursor ~= false then cursorX, cursorY, cursorScale = cursor(widget) end
    if widget.eyesTrailCenterX ~= centerX or widget.eyesTrailCenterY ~= centerY
        or widget.eyesTrailScale ~= cursorScale then clearTrails(widget) end
    widget.eyesTrailCenterX, widget.eyesTrailCenterY, widget.eyesTrailScale = centerX, centerY, cursorScale
    local trailElapsed = finite(elapsed) and elapsed > 0 and elapsed <= trailLifetime and elapsed or nil
    local trailActive = color.solid and widget.settings.glowTrails ~= false
        and widget.settings.followCursor ~= false and cursorX ~= nil and centerX ~= nil and centerY ~= nil
    for index, eye in ipairs(widget.eyes) do
        local eyeX = (index == 1 and -8 or 8) * factor
        if eye.factor ~= factor or eye.appearance ~= appearance or eye.color ~= color then
            clearTrail(eye)
            hideStandard(eye)
            hideSmooth(eye)
            if appearance == "smooth" then
                eye.smooth.orb:SetTexture(assetRoot .. "Orb.tga")
                position(eye.smooth.orb, (widget.content or widget.frame), eyeX, 0, 14 * factor, 16 * factor)
                eye.smooth.orb:SetVertexColor(1, 1, 1, 1)
                eye.smooth.iris:SetTexture(assetRoot .. (color.solid and "SolidIris" or "Iris") .. ".tga")
                eye.smooth.iris:SetVertexColor(color[1], color[2], color[3], 1)
                eye.smooth.glint:SetTexture(assetRoot .. "Glint.tga")
                eye.smooth.glint:SetVertexColor(1, 1, 1, 1)
            else
                for row, shape in ipairs(silhouette) do
                    eye.border[row]:SetColorTexture(0.05, 0.05, 0.05, 1)
                    position(eye.border[row], (widget.content or widget.frame), eyeX + shape[1] * factor,
                        shape[2] * factor, shape[3] * factor, shape[4] * factor)
                end
                for row, shape in ipairs(white) do
                    position(eye.white[row], (widget.content or widget.frame), eyeX + shape[1] * factor,
                        shape[2] * factor, shape[3] * factor, shape[4] * factor)
                    eye.white[row]:SetColorTexture(1, 1, 1, 1)
                end
                eye.pupil:SetColorTexture(color[1], color[2], color[3], 1)
                eye.spark:SetColorTexture(1, 1, 1, 1)
            end
            eye.factor, eye.appearance, eye.color = factor, appearance, color
        end
        local offsetX, offsetY = 0, 0
        if widget.settings.followCursor ~= false and cursorX and centerX and centerY then
            local dx, dy = cursorX - (centerX + eyeX), cursorY - centerY
            local distance = math.sqrt(dx * dx + dy * dy)
            if finite(distance) and distance > 0 then
                local proximity = math.min(1, distance / (18 * factor))
                local travelX, travelY = 3, 4
                if appearance == "smooth" then travelX, travelY = 2.8, 3.3 end
                if color.solid then travelX, travelY = 2.2, 2.8 end
                offsetX = dx / distance * travelX * factor * proximity
                offsetY = dy / distance * travelY * factor * proximity
            end
        end
        if appearance == "smooth" then
            local irisWidth, irisHeight = color.solid and 6 or 5.2, color.solid and 7 or 6
            updateTrail(widget, eye, eyeX, offsetX, offsetY, irisWidth * factor,
                irisHeight * factor, color, trailElapsed, trailActive)
            position(eye.smooth.iris, (widget.content or widget.frame), eyeX + offsetX, offsetY, irisWidth * factor, irisHeight * factor)
            local glintSize = 2
            position(eye.smooth.glint, (widget.content or widget.frame), eyeX + offsetX - factor,
                offsetY + factor, glintSize * factor, glintSize * factor)
        else
            updateTrail(widget, eye, eyeX, offsetX, offsetY, (color.solid and 5 or 4) * factor,
                (color.solid and 6 or 5) * factor, color, trailElapsed, trailActive)
            position(eye.pupil, (widget.content or widget.frame), eyeX + offsetX, offsetY,
                (color.solid and 5 or 4) * factor, (color.solid and 6 or 5) * factor)
            position(eye.spark, (widget.content or widget.frame), eyeX + offsetX - factor, offsetY + factor, factor, factor)
        end
    end
end

local function destroy(widget)
    clearTrails(widget)
    if widget.eyes then
        for _, eye in ipairs(widget.eyes) do
            hideStandard(eye)
            hideSmooth(eye)
            eye.factor, eye.appearance, eye.color = nil, nil, nil
        end
    end
    widget.eyesWidth = nil
end

Menubar:RegisterWidgetType({
    id = "eyes", name = "Eyes",
    retainOnDisable = true,
    defaults = { size = 16, followCursor = true, appearance = "smooth", iris = "blue", glowTrails = true},
    legacyDefaults = { appearance = "standard", iris = "black" },
    settings = {
        { key = "appearance", label = "Definition", type = "select", options = {
            { value = "standard", label = "Standard" },
            { value = "smooth", label = "High Definition" },
        } },
        { key = "iris", label = "Eye colour", type = "select", options = {
            { value = "brown", label = "Brown" }, { value = "black", label = "Black" },
            { value = "blue", label = "Blue" }, { value = "hazel", label = "Hazel" },
            { value = "grey", label = "Grey" }, { value = "red", label = "Red" },
            { value = "solidBlue", label = "Elven solid blue" }, { value = "solidOrange", label = "Elven solid orange" },
            { value = "solidRed", label = "Elven solid red" }, { value = "solidGreen", label = "Elven solid green" },
        } },
        { key = "glowTrails", label = "Elven glow trails", type = "toggle" },
        { key = "size", label = "Eye height", type = "select", options = {
            { value = 12, label = "Compact (12)" }, { value = 16, label = "Standard (16)" },
            { value = 20, label = "Large (20)" }, { value = 24, label = "Extra large (24)" },
        } },
        { key = "followCursor", label = "Follow the mouse pointer", type = "toggle" },
    },
    interval = 1 / 30,
    defaultPlacement = { bar = "top", alignment = "center", order = 1, sidebarOrder = 7 },
    create = create, update = update, reset = destroy, deactivate = destroy, destroy = destroy,
    tooltip = function(_, tip)
        tip:AddLine("Eyes")
        tip:AddLine("A little company for your adventures.", 1, 1, 1)
    end,
})
